    'php.modules.demo.application.demoseeder.p_platforma_pidtrymuie_pidkliuchennia_populiarnykh_u' => '<p>The platform supports integration with popular Ukrainian carriers via API. For a branch or parcel locker, the customer selects a city and pickup point without duplicating the mailing address.</p>',
