    'php.modules.storefront.infrastructure.dbalstorefrontcatalogquery.select_coalesce_at_name_ad_code_name_coalesce_pav_va' => 'SELECT COALESCE(at.name,ad.code) name,COALESCE(pav.value_text,CAST(pav.value_decimal AS CHAR),IF(pav.value_boolean=1,\'Yes\',IF(pav.value_boolean=0,\'No\',\'\'))) value FROM mc_product_attribute_value pav JOIN mc_attribute_definition ad ON ad.id=pav.attribute_id LEFT JOIN mc_attribute_translation at ON at.attribute_id=ad.id AND at.locale=? WHERE pav.product_id=? ORDER BY ad.sort_order,pav.sort_order,pav.id',
